<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreFinance {
 public static function coupon(PDO $db,array $actor,array $in):void {
  StoreAccess::require($db,$actor,'finance');$code=Security::text($in,'code',80);$percent=StoreCatalog::integer($in['percent']??null,1,100);$max=StoreCatalog::integer($in['max_uses']??1,1,10000000);$min=StoreCatalog::integer($in['min_total']??0,0,2000000000);$expires=Security::text($in,'expires',30);if(strtotime($expires)===false)throw new HttpError(422,'تاریخ انقضا معتبر نیست.');$rules=$in['rules']??[];if(!is_array($rules))throw new HttpError(422,'قواعد تخفیف معتبر نیستند.');foreach(['users','categories','products'] as $k){$rules[$k]??=[];if(!is_array($rules[$k])||count($rules[$k])>1000)throw new HttpError(422,'محدوده تخفیف معتبر نیست.');$rules[$k]=array_map(fn($v)=>StoreCatalog::integer($v,1),$rules[$k]);}foreach(['per_user','max_discount','starts'] as $k)$rules[$k]=StoreCatalog::integer($rules[$k]??0,0,2147483647);$rules['combine_sale']=!empty($rules['combine_sale']);
  Db::transaction($db,function()use($db,$actor,$code,$percent,$max,$min,$expires,$rules){$old=Db::query($db,'SELECT * FROM discounts WHERE code=?'.StoreAccess::lock($db),[$code])->fetch();if($old){if($max<$old['uses'])throw new HttpError(422,'سقف مصرف از مصرف فعلی کمتر نباشد.');Db::query($db,'UPDATE discounts SET percent=?,max_uses=?,min_total=?,expires=? WHERE code=?',[$percent,$max,$min,date('Y-m-d H:i:s',strtotime($expires)),$code]);}else Db::insert($db,'discounts',['code'=>$code,'percent'=>$percent,'max_uses'=>$max,'uses'=>0,'min_total'=>$min,'expires'=>date('Y-m-d H:i:s',strtotime($expires))]);if(Db::query($db,'SELECT code FROM store_coupon_rules WHERE code=?',[$code])->fetchColumn())Db::query($db,'UPDATE store_coupon_rules SET payload=? WHERE code=?',[Protocol::encode($rules),$code]);else Db::insert($db,'store_coupon_rules',['code'=>$code,'payload'=>Protocol::encode($rules)]);StoreAccess::audit($db,$actor,'coupon.save','discount',0,$old?:[],['code'=>$code,'percent'=>$percent,'rules'=>$rules]);});
 }
 private static function permit(PDO $db,array $actor):void {if(!StoreAccess::allows($db,$actor,'reports')&&!StoreAccess::allows($db,$actor,'finance'))throw new HttpError(403,'مجوز گزارش فروشگاه لازم است.');}
 private static function itemFilter(array $f):array {
  $parts=[];$args=[];foreach(['product'=>'sd.product_id','delivery'=>'sd.delivery','production'=>'sd.production','item_status'=>'sd.status','designer'=>'sd.assigned_user_id'] as $key=>$col)if(($f[$key]??'')!==''){$parts[]=$col.'=?';$args[]=Security::text($f,$key,80);}if(($f['category']??'')!==''){$parts[]='EXISTS(SELECT 1 FROM store_category_products cp WHERE cp.product_id=sd.product_id AND cp.category_id=?)';$args[]=StoreCatalog::integer($f['category'],1);}return [$parts?' AND '.implode(' AND ',$parts):'',$args];
 }
 public static function reports(PDO $db,array $actor,array $f,string $kind='orders'):array {
  self::permit($db,$actor);[$where,$args]=StoreOrders::where($db,$actor,$f);$base=' FROM orders o JOIN store_order_details d ON d.order_id=o.id LEFT JOIN payments p ON p.order_id=o.id WHERE '.$where;[$itemWhere,$itemArgs]=self::itemFilter($f);$items=' FROM order_items oi JOIN store_item_details sd ON sd.item_id=oi.id JOIN orders o ON o.id=oi.order_id JOIN store_order_details d ON d.order_id=o.id LEFT JOIN payments p ON p.order_id=o.id';$itemPaid=' WHERE '.$where.$itemWhere." AND p.status='verified'";
  if($kind==='orders')$sql='SELECT o.id,o.customer,o.phone,o.created_at,o.status,p.status AS payment_status,o.subtotal,o.discount,o.shipping,d.tax,o.total'.$base.' ORDER BY o.id DESC LIMIT 10001';
  elseif($kind==='items'){$sql='SELECT oi.id,oi.order_id,oi.title,oi.attributes,oi.quantity,oi.price,sd.delivery,sd.production,sd.status'.$items.' WHERE '.$where.$itemWhere.' ORDER BY oi.id DESC LIMIT 10001';array_push($args,...$itemArgs);}
  elseif($kind==='products'){$sql='SELECT oi.variant_id,oi.title,SUM(oi.quantity) AS quantity,SUM(oi.price*oi.quantity) AS total'.$items.$itemPaid.' GROUP BY oi.variant_id,oi.title ORDER BY total DESC LIMIT 10001';array_push($args,...$itemArgs);}
  elseif($kind==='categories'){$sql='SELECT c.id,c.title,SUM(oi.quantity) AS quantity,SUM(oi.price*oi.quantity) AS total'.$items.' JOIN store_category_products cp_report ON cp_report.product_id=sd.product_id JOIN store_categories c ON c.id=cp_report.category_id'.$itemPaid.' GROUP BY c.id,c.title ORDER BY total DESC LIMIT 10001';array_push($args,...$itemArgs);}
  elseif($kind==='customers')$sql="SELECT d.user_id,COUNT(*) AS orders,SUM(o.total) AS total,MAX(o.created_at) AS last_order".$base." AND p.status='verified' GROUP BY d.user_id ORDER BY total DESC LIMIT 10001";
  elseif($kind==='fulfillment'){$duration=$db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?'TIMESTAMPDIFF(SECOND,s.started_at,s.completed_at)':'CAST((julianday(s.completed_at)-julianday(s.started_at))*86400 AS INTEGER)';$sql='SELECT oi.id,oi.order_id,oi.title,sd.production,sd.status,s.due_at,s.started_at,s.completed_at,CASE WHEN s.completed_at>=s.started_at THEN '.$duration.' ELSE NULL END AS duration_seconds'.$items.' LEFT JOIN store_item_schedule s ON s.item_id=oi.id WHERE '.$where.$itemWhere.' ORDER BY oi.id DESC LIMIT 10001';array_push($args,...$itemArgs);}
  elseif(in_array($kind,['inventory','movements'],true)){$iv=['1=1'];$args=[];if(($f['product']??'')!==''){$iv[]='v.product_id=?';$args[]=StoreCatalog::integer($f['product'],1);}if(($f['category']??'')!==''){$iv[]='EXISTS(SELECT 1 FROM store_category_products cp WHERE cp.product_id=v.product_id AND cp.category_id=?)';$args[]=StoreCatalog::integer($f['category'],1);}if($kind==='movements'){foreach(['from'=>'>=','to'=>'<='] as $k=>$op)if(($f[$k]??'')!==''){$iv[]='m.created_at'.$op.'?';$args[]=Security::text($f,$k,10).($k==='to'?' 23:59:59':' 00:00:00');}$sql='SELECT m.id,v.sku,p.title,m.delta,m.before_stock,m.after_stock,m.reason,m.user_id,m.created_at FROM store_inventory_movements m JOIN variants v ON v.id=m.variant_id JOIN products p ON p.id=v.product_id WHERE '.implode(' AND ',$iv).' ORDER BY m.id DESC LIMIT 10001';}else $sql='SELECT v.sku,p.title,v.attributes,v.stock,COALESCE(vd.reorder_point,0) AS reorder_point FROM variants v JOIN products p ON p.id=v.product_id LEFT JOIN store_variant_details vd ON vd.variant_id=v.id WHERE '.implode(' AND ',$iv).' ORDER BY v.id LIMIT 10001';}
  elseif($kind==='shipments')$sql='SELECT s.id,s.order_id,s.carrier,s.tracking,s.status,s.actual_cost,s.created_at FROM store_shipments s JOIN orders o ON o.id=s.order_id JOIN store_order_details d ON d.order_id=o.id LEFT JOIN payments p ON p.order_id=o.id WHERE '.$where.' ORDER BY s.id DESC LIMIT 10001';
  elseif($kind==='refunds')$sql='SELECT r.id,r.order_id,r.amount,r.reason,r.reference,r.status,r.created_at FROM store_refunds r JOIN orders o ON o.id=r.order_id JOIN store_order_details d ON d.order_id=o.id LEFT JOIN payments p ON p.order_id=o.id WHERE '.$where.' ORDER BY r.id DESC LIMIT 10001';
  else throw new HttpError(422,'نوع گزارش معتبر نیست.');
  $rows=Db::query($db,$sql,$args)->fetchAll();if(count($rows)>10000)throw new HttpError(422,'بازه گزارش را محدود کنید؛ حداکثر ۱۰۰۰۰ ردیف.');$columns=$f['columns']??[];if($columns){if(!is_array($columns)||count($columns)>30)throw new HttpError(422,'ستون‌ها معتبر نیستند.');foreach($columns as $col)if(!is_string($col)||!preg_match('/^[a-z_]+$/D',$col))throw new HttpError(422,'ستون گزارش معتبر نیست.');$rows=array_map(fn($r)=>array_intersect_key($r,array_flip($columns)),$rows);if($rows&&!$rows[0])throw new HttpError(422,'ستون متناسب با نوع گزارش انتخاب کنید.');}return $rows;
 }
 public static function dashboard(PDO $db,array $actor,array $f):array {
  self::permit($db,$actor);[$where,$args]=StoreOrders::where($db,$actor,$f);$base=' FROM orders o JOIN store_order_details d ON d.order_id=o.id LEFT JOIN payments p ON p.order_id=o.id WHERE '.$where;$paid="CASE WHEN p.status='verified' THEN ";$stats=Db::query($db,'SELECT COUNT(*) AS orders,SUM('.$paid.'1 ELSE 0 END) AS paid,COALESCE(SUM('.$paid.'o.subtotal ELSE 0 END),0) AS gross,COALESCE(SUM('.$paid.'o.discount ELSE 0 END),0) AS discount,COALESCE(SUM('.$paid.'o.shipping ELSE 0 END),0) AS shipping,COALESCE(SUM('.$paid.'o.total ELSE 0 END),0) AS receipts'.$base,$args)->fetch();foreach($stats as &$v)$v=(int)$v;unset($v);$refund=(int)Db::query($db,"SELECT COALESCE(SUM(r.amount),0) FROM store_refunds r WHERE r.status='test_refunded' AND r.order_id IN(SELECT o.id".$base.')',$args)->fetchColumn();$days=[];foreach(Db::query($db,"SELECT SUBSTR(o.created_at,1,10) AS day,SUM(o.total) AS amount".$base." AND p.status='verified' GROUP BY SUBSTR(o.created_at,1,10) ORDER BY day",$args)->fetchAll() as $row)$days[$row['day']]=(int)$row['amount'];
  $low=Db::query($db,'SELECT v.sku,p.title,v.stock,COALESCE(vd.reorder_point,0) AS threshold FROM variants v JOIN products p ON p.id=v.product_id LEFT JOIN store_variant_details vd ON vd.variant_id=v.id WHERE COALESCE(vd.unlimited,0)=0 AND v.stock<=COALESCE(vd.reorder_point,0) ORDER BY v.stock LIMIT 30')->fetchAll();$custom=(int)Db::query($db,"SELECT COUNT(*) FROM store_item_details sd JOIN order_items oi ON oi.id=sd.item_id WHERE sd.production='custom' AND sd.status='new' AND oi.order_id IN(SELECT o.id".$base.')',$args)->fetchColumn();$paidItems=Db::query($db,"SELECT COUNT(*) AS items,SUM(CASE WHEN sd.production='custom' THEN 1 ELSE 0 END) AS custom FROM store_item_details sd JOIN order_items oi ON oi.id=sd.item_id WHERE oi.order_id IN(SELECT o.id".$base." AND p.status='verified')",$args)->fetch();return $stats+['refund'=>$refund,'net'=>$stats['receipts']-$refund,'average'=>$stats['paid']?(int)round($stats['receipts']/$stats['paid']):0,'days'=>$days,'low'=>$low,'new_custom'=>$custom,'custom_rate'=>$paidItems['items']?round(100*$paidItems['custom']/$paidItems['items'],1):0];
 }
}
